  "settings.retentionExtraTargets": "Los destinos externos adicionales mantienen sus propias reglas, que configuras en la página Externo.",
  "settings.retentionOffsiteScope": "Estas reglas se aplican al destino externo principal de cada sección, es decir, la dirección de su campo externo. Cualquier otro destino externo, incluso uno creado a partir de un destino, mantiene sus propias reglas. Si ahí solo hay ceros, BombVault nunca lo poda.",
  "settings.retentionCombineInfo": "Las cinco reglas se combinan con O: una copia sobrevive si cualquier regla la conservaría. No se suman a un número fijo. Se aplica por separado a cada elemento respaldado.",

  // Off-site (rclone)
  "rclone.title": "Externo (rclone)",
  "rclone.hint": "Pega una configuración de rclone para copiar a la nube (Backblaze B2, S3, Google Drive, …). Se guarda cifrada. SMB/NFS no necesitan rclone: monta el recurso compartido en Unraid y asígnale una Ruta de copia.",
  "rclone.configured": "Remotos configurados",
  "rclone.pathHint": "Luego asigna una Ruta de copia a «rclone:<remote>:<bucket>/path» para enviar esa sección fuera del sitio.",
  "cloud.title": "Credenciales de nube compartidas (S3 / restic REST)",
  "cloud.hint": "Credenciales para backends remotos de restic, sin rclone. Tras guardar, establece una ruta de copia a un repo remoto, p. ej. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo o sftp:user@host:/repo. Los secretos se guardan cifrados y no se vuelven a mostrar.",
  "cloud.secretSet": "guardado, déjalo vacío para conservar",
  "cloud.storageClass.label": "Clase de almacenamiento off-site",
  "cloud.storageClass.default": "(predeterminado del proveedor)",
  "cloud.storageClass.hint": "Se aplica solo a los backends S3 nativos (repositorios que empiezan por s3:). Los niveles de archivo profundo (Glacier Flexible Retrieval, Deep Archive) no se ofrecen a propósito porque rompen la restauración de restic.",
  "cloud.credSets.title": "Conjuntos de credenciales adicionales",
  "cloud.credSets.hint": "Asigna a uno o más destinos externos sus propias credenciales S3 o restic REST, en lugar de compartir las de arriba.",
  "cloud.credSets.add": "Añadir conjunto de credenciales",
  "cloud.credSets.name": "Nombre",
  "cloud.credSets.none": "Aún no hay conjuntos de credenciales adicionales.",
  "cloud.credSets.kept": "{name} (credenciales conservadas)",
  "export.encrypt.hint": "Los repositorios de restic ya están cifrados. Esto cifra opcionalmente los artefactos de exportación en texto plano (tar.gz de contenedor y VM junto con sus xml, y el zip flash) con age, para que se puedan almacenar o mover fuera del servidor de forma segura.",
  "export.encrypt.ageInfo": "age (age-encryption.org) es una herramienta de cifrado de archivos pequeña y moderna: una alternativa más sencilla a GPG para sellar un archivo para uno o varios destinatarios.",
  "export.encrypt.enable": "Cifrar exportaciones con age",
  "export.encrypt.enableHint": "Cuando está activado, las exportaciones de contenedor, VM y flash se sellan con age antes de escribirse en disco y reciben el sufijo .age.",
  "export.encrypt.kitSealed": "El kit de recuperación también se sella y llega como bombvault-recovery-kit.md.age. Sigue siendo texto legible (armadura ASCII), así que todavía se puede pegar en un gestor de contraseñas o imprimir, pero necesitarás tu clave privada age para abrirlo: guarda esa clave en un sitio que no dependa del propio kit.",
  "export.encrypt.recipients": "Destinatarios age",
  "export.encrypt.recipientsHint": "Un destinatario por línea. Usa una clave pública age (age1...) o una clave pública SSH. La clave privada correspondiente es necesaria para descifrar fuera del servidor. Con el cifrado activado y sin un destinatario válido, la exportación falla en lugar de escribir texto plano.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Añade al menos un destinatario age, de lo contrario la exportación cifrada fallará.",
  "rclone.save": "Guardar configuración",

