  "dbdump.databasesLine": "Bases de datos: {names}",
  "dbdump.damagedBadge": "Dañado",
  "dbdump.damagedHint": "Este volcado no pasó sus comprobaciones y no se pudo eliminar automáticamente. No se puede descargar ni importar. Bórralo.",
  "dbdump.download": "Descargar",
  "dbdump.format": "Formato de archivo",
  "dbdump.formatSql": ".sql",
  "dbdump.formatGz": ".sql.gz (comprimido)",
  "dbdump.downloadRefused": "Se rechazó la descarga",
  "dbdump.saveToFolder": "Guardar en una carpeta",
  "dbdump.saveHint": "Escribe el volcado como archivo en la carpeta elegida del servidor, con nobody:users como propietario para que puedas abrirlo por el recurso compartido de red. El archivo contiene todas las tablas y los hash de contraseña de los usuarios de la base de datos; guárdalo donde solo llegues tú.",
  "dbdump.saveCancelHint": "Cancelar detiene el guardado y elimina el archivo sin terminar.",
  "dbdump.savedTo": "Guardado en {path}",
  "dbdump.import": "Importar en una base de datos nueva",
  "dbdump.importConfirm": "¿Importar este volcado de {engine} {version} en {container}? BombVault para el contenedor, aparta su carpeta de datos (se conserva, no se borra nada), arranca el contenedor con una carpeta de datos vacía e importa el volcado. Las aplicaciones que usan esta base de datos verán su estado del momento del volcado.",
  "dbdump.importConfirmNoVersion": "¿Importar este volcado de {engine} en {container}? BombVault para el contenedor, aparta su carpeta de datos (se conserva, no se borra nada), arranca el contenedor con una carpeta de datos vacía e importa el volcado. Las aplicaciones que usan esta base de datos verán su estado del momento del volcado.",
  "dbdump.importNoVersion": "Este volcado no registra la versión de su base de datos. La importación falla si el servidor no puede leerlo.",
  "dbdump.importStops": "one=Mientras importa, BombVault también detiene {apps} y después la vuelve a iniciar. Si la importación falla una vez empezada, los datos antiguos se quedan apartados y la aplicación detenida.|many=Mientras importa, BombVault también detiene estas aplicaciones: {apps}. Después las vuelve a iniciar. Si la importación falla una vez empezada, los datos antiguos se quedan apartados y las aplicaciones detenidas.|other=Mientras importa, BombVault también detiene estas aplicaciones: {apps}. Después las vuelve a iniciar. Si la importación falla una vez empezada, los datos antiguos se quedan apartados y las aplicaciones detenidas.",
  "dbdump.importDone": "Base de datos importada.",
  "dbdump.importRefused.busy": "Hay otra copia de seguridad o restauración en marcha. Vuelve a intentarlo cuando termine.",
  "dbdump.importRefused.notRunning": "Arranca antes el contenedor; la importación necesita el servidor en marcha.",
  "dbdump.importRefused.engineMismatch": "Este volcado viene de un tipo de base de datos distinto del que ejecuta el contenedor.",
  "dbdump.importRefused.noDataMount": "BombVault no alcanza la carpeta de datos de este contenedor, así que no puede apartarla con seguridad. Importa el volcado a mano como describe el kit de recuperación.",
  "dbdump.importRefused.version": "El servidor funciona con la versión {server} y el volcado viene de {dump}. Usa una imagen con la versión {dump} o más reciente para esta importación.",
  "dbdump.importRefused.versionSameMajor": "El servidor funciona con la versión {server} y el volcado viene de {dump}. MySQL y MariaDB solo importan un volcado en la versión mayor de la que procede, así que usa una imagen con la versión {dump} para esta importación.",
