  "zfs.safety.hint": "BombVault tomó estas instantáneas justo antes de restaurar en un conjunto de datos, para que el estado previo se pueda recuperar. BombVault nunca las borra por su cuenta. Para recuperar archivos sueltos, cópialos desde .zfs/snapshot/<name> dentro del conjunto de datos. zfs rollback solo funciona mientras sea la instantánea más reciente de ese conjunto; zfs rollback -r borra todas las posteriores, incluidas las automáticas.",
