  "recovery.abTitle": "Importar desde el plugin Appdata.Backup",
  "recovery.abIntro": "Convierte los archivos que escribió el plugin Appdata.Backup en puntos de restauración de los contenedores correspondientes, cada uno con la fecha en que el plugin lo creó. Los archivos solo se leen, nunca se modifican ni se borran. Cada uno se descomprime junto al repositorio, se copia y la copia descomprimida se vuelve a borrar, así que ese lugar necesita espacio para el archivo más grande.",
