  "recovery.foreignKey": "APP_KEY de la otra instancia",
  "recovery.foreignKeyHint": "La clave de 64 caracteres del kit de recuperación de la OTRA instancia. Tu propia clave queda intacta.",
  "recovery.foreignCredsIntro": "Esto parece un repositorio remoto, así que necesita las credenciales del backend del OTRO servidor. Solo se usan en esta sesión y nunca se guardan. Tus propias credenciales externas no se reutilizan aquí a propósito: se enviarían a una dirección que acabas de escribir.",
