  "mcp.allowStart": "Permitir iniciar copias",
  "mcp.allowStartHint": "Con esto activado, el asistente puede iniciar la copia de un elemento, de un dominio entero o de la copia total, y cancelar las copias que ha iniciado: como mucho {n} por hora, con {minutes} minutos de separación para el mismo elemento y {perDay} por elemento y día. Una copia detiene los contenedores en marcha hasta que termina. Sin esto, la clave solo puede leer.",
