  "api.title": "Tokens de API",
  "api.hint": "Tokens para scripts, paneles y domótica. Un token abre la API en /api/v1 y nada más. Las restauraciones, los borrados y los ajustes se quedan en esta interfaz web.",
  "api.addressLabel": "Dirección de la API",
