  "ha.title": "Home Assistant",
  "ha.hint": "Envía el estado de las copias a Home Assistant a través de un broker MQTT. BombVault aparece allí como un dispositivo con sensores y un botón de copia por sección. Apunta la integración MQTT de Home Assistant al mismo broker.",
